const EvolvingPath: React.FC<{
  d: string;
  progress: number;
  stroke: string;
  strokeWidth: number;
  fill?: string;
}> = ({ d, progress, stroke, strokeWidth, fill = "none" }) => {
  const clampedStrokeProgress = Math.min(1, Math.max(0, progress * 1.5));
  const fillOpacity =
    fill !== "none" ? Math.min(1, Math.max(0, (progress - 0.6) * 2.5)) : 0;
  const evolution = evolvePath(clampedStrokeProgress, d);

  return (
    <path
      d={d}
      stroke={stroke}
      strokeWidth={strokeWidth}
      fill={fill}
      fillOpacity={fillOpacity}
      strokeDasharray={evolution.strokeDasharray}
      strokeDashoffset={evolution.strokeDashoffset}
      style={{ transition: "none" }}
    />
  );
};

