const DebtBlock: React.FC<{
  levels: number;
  filledLevels: number;
  color: string;
  blueColor: string;
  progress: number;
}> = ({ levels, filledLevels, color, blueColor, progress }) => {
  const boxW = 100;
  const boxH = 20;
  const padding = 20;
  const totalH = levels * boxH;
  const outerW = boxW + padding * 2;
  const outerH = totalH + padding * 2;

  const outerPath = `M ${padding} 0 L ${outerW - padding} 0 A ${padding} ${padding} 0 0 1 ${outerW} ${padding} L ${outerW} ${outerH - padding} A ${padding} ${padding} 0 0 1 ${outerW - padding} ${outerH} L ${padding} ${outerH} A ${padding} ${padding} 0 0 1 0 ${outerH - padding} L 0 ${padding} A ${padding} ${padding} 0 0 1 ${padding} 0 Z`;

  return (
    <div style={{ position: "relative", width: outerW, height: outerH }}>
      <svg width={outerW} height={outerH} style={{ position: "absolute", top: 0, left: 0 }}>
        <EvolvingPath d={outerPath} progress={progress} stroke={color} strokeWidth={4} />
        {Array.from({ length: levels }).map((_, i) => {
          const isFilled = levels - 1 - i < filledLevels;
          const y = padding + i * boxH;
          const rectPath = `M ${padding} ${y} h ${boxW} v ${boxH} h -${boxW} Z`;
          return (
            <EvolvingPath
              key={i}
              d={rectPath}
              progress={progress}
              stroke={isFilled ? blueColor : color}
              strokeWidth={4}
              fill={isFilled ? blueColor : "none"}
            />
          );
        })}
      </svg>
    </div>
  );
};

